// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(bytes32 guess, uint256 actorSeed) public {
        vm.assume(guess != bytes32(0));

        address actor = vm.addr(uint256(keccak256(abi.encode(actorSeed))) | 1);
        vm.deal(actor, 2 ether);

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        uint256 guessBlock = block.number + 1;
        vm.roll(guessBlock);
        vm.roll(guessBlock + 1);

        uint256 beforeBal = actor.balance;

        vm.prank(actor);
        c.settle();

        bytes32 answer = blockhash(guessBlock);
        bool shouldPay = answer != bytes32(0) && guess == answer;

        bool paid = actor.balance > beforeBal;

        assertTrue(paid == shouldPay);
    }
}
